import {createApp} from '../../src/server.mjs';import {mkdtempSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';
const app=createApp({dir:mkdtempSync(join(tmpdir(),'cc-fields-ui-')),master:'f'.repeat(64),bootstrap:'fields-ui'});await new Promise(r=>app.server.listen(4199,'127.0.0.1',r));
const r=await fetch('http://127.0.0.1:4199/v1/auth/bootstrap',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:'fields-ui',email:'fields@local.test',password:'Fields-local-test-2026'})});const owner=await r.json();app.store.mutate(owner.workspaceId,d=>{const f=d.funnels[0];d.leads.push({id:'fields-customer',name:'Cliente campos QA',phone:'5522991234567',funnelId:f.id,stage:f.stages[0].name,custom:{},status:'open',createdAt:new Date().toISOString()});d.inboxEvents.push({id:crypto.randomUUID(),type:'message',leadId:'fields-customer',direction:'in',text:'Teste local de perfil e campos',at:new Date().toISOString()});});console.log('http://127.0.0.1:4199/account · fields@local.test / Fields-local-test-2026');
